1	package org.jsoup.nodes;
2	
3	import org.jsoup.Connection;
4	import org.jsoup.Jsoup;
5	import org.jsoup.helper.HttpConnection;
6	import org.jsoup.helper.Validate;
7	import org.jsoup.parser.Tag;
8	import org.jsoup.select.Elements;
9	import org.jsoup.select.Evaluator;
10	import org.jsoup.select.Selector;
11	import org.jspecify.annotations.Nullable;
12	
13	import java.util.ArrayList;
14	import java.util.List;
15	
16	/**
17	 * An HTML Form Element provides ready access to the form fields/controls that are associated with it. It also allows a
18	 * form to easily be submitted.
19	 */
20	public class FormElement extends Element {
21	    private Elements linkedEls = new Elements();
22	    // contains form submittable elements that were linked during the parse (and due to parse rules, may no longer be a child of this form)
23	    // all form-listed elements, per the HTML spec: button, fieldset, input, keygen, object, output, select, textarea
24	    private static final Evaluator formListed = Selector.evaluatorOf(
25	        "button, fieldset, input, keygen, object, output, select, textarea");
26	
27	    /**
28	     * Create a new, standalone form element.
29	     *
30	     * @param tag        tag of this element
31	     * @param baseUri    the base URI
32	     * @param attributes initial attributes
33	     */
34	    public FormElement(Tag tag, @Nullable String baseUri, @Nullable Attributes attributes) {
35	        super(tag, baseUri, attributes);
36	    }
37	
38	    /**
39	     * Get the list of form control elements associated with this form. A control is associated either through a
40	     * matching {@code form="<id>"} attribute (resolved to the first form in the document with that id), or, when no
41	     * such attribute is present, through its nearest ancestor {@code <form>}; controls linked to this form by the
42	     * parser but relocated by parse rules (such as those fostered out of a form inside a table) are included too.
43	     * The list is freshly computed in document order and reflects the current state of the DOM.
44	     * @return form controls associated with this element.
45	     */
46	    public Elements elements() {
47	        Elements els = new Elements();
48	        Document owner = ownerDocument();
49	        if (owner == null) {
50	            // an orphaned, stand-alone form: fall back to its current descendants and parser-linked controls
51	            els.addAll(select(formListed));
52	            for (Element linkedEl : linkedEls) {
53	                if (!els.contains(linkedEl)) els.add(linkedEl);
54	            }
55	            return els;
56	        }
57	
58	        // a form="<id>" reference resolves, in tree order, to the first <form> with that id
59	        String formId = id();
60	        boolean referencedFormsResolveHere = formId.length() == 0 || firstFormWithId(owner, formId) == this;
61	
62	        for (Element el : owner.select(formListed)) {
63	            if (isFormOwner(el, formId, referencedFormsResolveHere))
64	                els.add(el);
65	        }
66	        return els; // owner.select yields elements in document order, and each is visited at most once
67	    }
68	
69	    private static @Nullable Element firstFormWithId(Document owner, String formId) {
70	        for (Element form : owner.select("form")) {
71	            if (formId.equals(form.id())) return form;
72	        }
73	        return null;
74	    }
75	
76	    /**
77	     * Determine whether this form is the form owner of the given control, following the HTML association rules:
78	     * an explicit {@code form} attribute wins and resolves to the first form with that id; otherwise the nearest
79	     * form ancestor owns it, falling back to the parser-established link for controls displaced by parse rules.
80	     */
81	    private boolean isFormOwner(Element el, String formId, boolean referencedFormsResolveHere) {
82	        String referenced = el.attr("form");
83	        if (referenced.length() > 0)
84	            return referencedFormsResolveHere && referenced.equals(formId);
85	
86	        for (Element ancestor = el.parentElement(); ancestor != null; ancestor = ancestor.parentElement()) {
87	            if (ancestor.nameIs("form")) return ancestor == this;
88	        }
89	        // no form ancestor: retain the association established while parsing (e.g. fostered out of a table form)
90	        return linkedEls.contains(el);
91	    }
92	
93	    /**
94	     * Add a form control element to this form.
95	     * @param element form control to add
96	     * @return this form element, for chaining
97	     */
98	    public FormElement addElement(Element element) {
99	        linkedEls.add(element);
100	        return this;
101	    }
102	
103	    @Override
104	    protected void removeChild(Node out) {
105	        super.removeChild(out);
106	        linkedEls.remove(out);
107	    }
108	
109	    /**
110	     * Prepare to submit this form. A Connection object is created with the request set up from the form values. This
111	     * Connection will inherit the settings and the cookies (etc) of the connection/session used to request this Document
112	     * (if any), as available in {@link Document#connection()}
113	     <p>You can then set up other options (like user-agent, timeout, cookies), then execute it.</p>
114	
115	     @return a connection prepared from the values of this form, in the same session as the one used to request it
116	     @throws IllegalArgumentException if the form's absolute action URL cannot be determined. Make sure you pass the
117	     document's base URI when parsing.
118	     */
119	    public Connection submit() {
120	        String action = hasAttr("action") ? absUrl("action") : baseUri();
121	        Validate.notEmpty(action, "Could not determine a form action URL for submit. Ensure you set a base URI when parsing.");
122	        Connection.Method method = attr("method").equalsIgnoreCase("POST") ?
123	                Connection.Method.POST : Connection.Method.GET;
124	
125	        Document owner = ownerDocument();
126	        Connection connection = owner != null? owner.connection().newRequest() : Jsoup.newSession();
127	        return connection.url(action)
128	                .data(formData())
129	                .method(method);
130	    }
131	
132	    /**
133	     * Get the data that this form submits. The returned list is a copy of the data, and changes to the contents of the
134	     * list will not be reflected in the DOM.
135	     * @return a list of key vals
136	     */
137	    public List<Connection.KeyVal> formData() {
138	        ArrayList<Connection.KeyVal> data = new ArrayList<>();
139	
140	        // iterate the form control elements and accumulate their values
141	        for (Element el: elements()) {
142	            if (!el.tag().isFormSubmittable()) continue; // contents are form listable, superset of submitable
143	            if (el.hasAttr("disabled")) continue; // skip disabled form inputs
144	            String name = el.attr("name");
145	            if (name.length() == 0) continue;
146	            String type = el.attr("type");
147	
148	            if (type.equalsIgnoreCase("button") || type.equalsIgnoreCase("image")) continue; // browsers don't submit these
149	
150	            if (el.nameIs("select")) {
151	                addSelectData(name, el, data);
152	            } else if ("checkbox".equalsIgnoreCase(type) || "radio".equalsIgnoreCase(type)) {
153	                // only add checkbox or radio if they have the checked attribute
154	                if (el.hasAttr("checked") && !isDisabledByFieldset(el, type)) {
155	                    final String val = el.val().length() >  0 ? el.val() : "on";
156	                    data.add(HttpConnection.KeyVal.create(name, val));
157	                }
158	            } else {
159	                if (isDisabledByFieldset(el, type)) continue;
160	                data.add(HttpConnection.KeyVal.create(name, el.val()));
161	            }
162	        }
163	        return data;
164	    }
165	
166	    private void addSelectData(String name, Element select, ArrayList<Connection.KeyVal> data) {
167	        if (isDisabledByFieldset(select, "")) return;
168	
169	        boolean multiple = select.hasAttr("multiple");
170	        Elements options = select.select("option");
171	        Element firstEnabled = null;
172	        boolean submitted = false;
173	
174	        for (Element option : options) {
175	            if (!optionEnabled(option)) continue;
176	            if (firstEnabled == null) firstEnabled = option;
177	            if (option.hasAttr("selected")) {
178	                data.add(HttpConnection.KeyVal.create(name, option.val()));
179	                submitted = true;
180	                if (!multiple) return; // single-select submits the first selected enabled option, in final order
181	            }
182	        }
183	
184	        if (!submitted && !multiple && firstEnabled != null) {
185	            // single-select with no enabled selected option falls back to the first enabled option
186	            data.add(HttpConnection.KeyVal.create(name, firstEnabled.val()));
187	        }
188	        // multi-select with no enabled selections, or a single-select with no enabled options, submits nothing
189	    }
190	
191	    private boolean optionEnabled(Element option) {
192	        if (option.hasAttr("disabled")) return false;
193	        // an option is also unavailable when its nearest enclosing <optgroup> is disabled
194	        for (Element ancestor = option.parentElement();
195	             ancestor != null && ancestor.nameIs("optgroup");
196	             ancestor = ancestor.parentElement()) {
197	            if (ancestor.hasAttr("disabled")) return false;
198	        }
199	        return true;
200	    }
201	
202	    /**
203	     * Per the HTML spec, a disabled fieldset excludes all of its descendant controls except those within the subtree
204	     * of its first direct {@code <legend>} child. The exception does not extend to siblings or nested fieldsets outside
205	     * that legend. An {@code <input type="hidden">} is not disabled by a fieldset.
206	     */
207	    private boolean isDisabledByFieldset(Element control, String type) {
208	        if ("hidden".equalsIgnoreCase(type)) return false;
209	        Element ancestor = control.parent();
210	        while (ancestor != null) {
211	            if (ancestor.nameIs("fieldset") && ancestor.hasAttr("disabled")) {
212	                Element legend = firstLegendChild(ancestor);
213	                if (legend == null || !isDescendant(control, legend)) return true;
214	                // control is inside the exempt first legend; continue checking ancestors outside of this fieldset
215	                ancestor = ancestor.parent();
216	            } else {
217	                ancestor = ancestor.parent();
218	            }
219	        }
220	        return false;
221	    }
222	
223	    private @Nullable Element firstLegendChild(Element fieldset) {
224	        for (Element child : fieldset.children()) {
225	            if (child.nameIs("legend")) return child;
226	        }
227	        return null;
228	    }
229	
230	    private boolean isDescendant(Element node, Element ancestor) {
231	        Node parent = node.parentNode();
232	        while (parent != null) {
233	            if (parent == ancestor) return true;
234	            parent = parent.parentNode();
235	        }
236	        return false;
237	    }
238	
239	    @Override
240	    public FormElement clone() {
241	        return (FormElement) super.clone();
242	    }
243	
244	    @Override
245	    protected FormElement doClone(@Nullable Node parent) {
246	        FormElement clone = (FormElement) super.doClone(parent);
247	        // don't share the parser-linked list; its members belong to the source tree, and the clone's descendants stay
248	        // associated through their form ancestry
249	        clone.linkedEls = new Elements();
250	        return clone;
251	    }
252	}
