        // P: single select, only selection is disabled -> fall back first enabled; then remove selected
        String html4 = "<form id=f><select name=s><option value=d selected disabled>" +
            "<option value=a><option value=b disabled></select></form>";
        FormElement f4 = Jsoup.parse(html4).expectForm("#f");
        System.out.println("P: " + data(f4)); // expect s=a

        // Q: fostered form in table with fieldset
        String html5 = "<form id=f><table><fieldset disabled><legend><input name=leg value=L></legend>" +
            "<input name=a value=A></fieldset><tr><td><input name=b value=B></td></tr></table></form>";
        FormElement f5 = Jsoup.parse(html5).expectForm("#f");
        System.out.println("Q: [" + data(f5) + "]");
        System.out.println("--- tree Q ---");
        System.out.println(f5.ownerDocument().body().html());
    }
}
