import org.jsoup.Jsoup;
import org.jsoup.nodes.*;
import org.jsoup.Connection;

public class Probe5 {
    static String data(FormElement f) {
        StringBuilder sb = new StringBuilder();
        for (Connection.KeyVal kv : f.formData()) {
            if (sb.length()>0) sb.append('&');
            sb.append(kv.key()).append('=').append(kv.value());
        }
        return sb.toString();
    }
    public static void main(String[] args) {
        // option with no value attr -> browser submits its text
        System.out.println("option no value: [" + data(Jsoup.parse(
          "<form id=f><select name=s><option>hello</option></select></form>").expectForm("#f")) + "]");
        // option empty value attr
        System.out.println("option empty value: [" + data(Jsoup.parse(
          "<form id=f><select name=s><option value=>x</option></select></form>").expectForm("#f")) + "]");
        // fallback option no value
        System.out.println("fallback no value: [" + data(Jsoup.parse(
          "<form id=f><select name=s><option>abc</option><option>def</option></select></form>").expectForm("#f")) + "]");
        // hidden disabled
        System.out.println("hidden disabled own: [" + data(Jsoup.parse(
          "<form id=f><input type=hidden name=h value=H disabled><input type=hidden name=h2 value=H2></form>").expectForm("#f")) + "]");
        // input inside disabled button
        System.out.println("input in disabled button: [" + data(Jsoup.parse(
          "<form id=f><button disabled><input name=x value=1></button><input name=y value=2></form>").expectForm("#f")) + "]");
        // fieldset disabled first legend with leading sibling
        System.out.println("legend after p: [" + data(Jsoup.parse(
          "<form id=f><fieldset disabled><p></p><legend><input name=l value=1></legend><input name=a value=2></fieldset></form>").expectForm("#f")) + "]");
    }
}
