17	
18	/**
19	 * An HTML Form Element provides ready access to the form fields/controls that are associated with it. It also allows a
20	 * form to easily be submitted.
21	 */
22	public class FormElement extends Element {
23	    private final Elements linkedEls = new Elements();
24	    // contains form submittable elements that were linked during the parse (and due to parse rules, may no longer be a child of this form)
25	    private static final Evaluator submittable = Selector.evaluatorOf(StringUtil.join(SharedConstants.FormSubmitTags, ", "));
26	
27	    /**
28	     * Create a new, standalone form element.
29	     *
30	     * @param tag        tag of this element
31	     * @param baseUri    the base URI
32	     * @param attributes initial attributes
33	     */
34	    public FormElement(Tag tag, @Nullable String baseUri, @Nullable Attributes attributes) {
35	        super(tag, baseUri, attributes);
36	    }
37	
38	    /**
39	     * Get the list of form control elements associated with this form.
40	     * @return form controls associated with this element.
41	     */
42	    public Elements elements() {
43	        // As elements may have been added or removed from the DOM after parse, prepare a new list that unions them:
44	        Elements els = select(submittable); // current form children
45	        for (Element linkedEl : linkedEls) {
46	            if (linkedEl.ownerDocument() != null && !els.contains(linkedEl)) {
47	                els.add(linkedEl); // adds previously linked elements, that weren't previously removed from the DOM
48	            }
49	        }
50	
51	        return els;
52	    }
53	
54	    /**
55	     * Add a form control element to this form.
56	     * @param element form control to add
57	     * @return this form element, for chaining
58	     */
59	    public FormElement addElement(Element element) {
60	        linkedEls.add(element);
61	        return this;
62	    }
63	
64	    @Override
65	    protected void removeChild(Node out) {
66	        super.removeChild(out);
67	        linkedEls.remove(out);
68	    }
69	
70	    /**
71	     Prepare to submit this form. A Connection object is created with the request set up from the form values. This
72	     Connection will inherit the settings and the cookies (etc) of the connection/session used to request this Document
73	     (if any), as available in {@link Document#connection()}
74	     <p>You can then set up other options (like user-agent, timeout, cookies), then execute it.</p>
75	
76	     @return a connection prepared from the values of this form, in the same session as the one used to request it
77	     @throws IllegalArgumentException if the form's absolute action URL cannot be determined. Make sure you pass the
78	     document's base URI when parsing.
79	     */
80	    public Connection submit() {
81	        String action = hasAttr("action") ? absUrl("action") : baseUri();
82	        Validate.notEmpty(action, "Could not determine a form action URL for submit. Ensure you set a base URI when parsing.");
83	        Connection.Method method = attr("method").equalsIgnoreCase("POST") ?
84	                Connection.Method.POST : Connection.Method.GET;
85	
86	        Document owner = ownerDocument();
87	        Connection connection = owner != null? owner.connection().newRequest() : Jsoup.newSession();
88	        return connection.url(action)
89	                .data(formData())
90	                .method(method);
91	    }
92	
93	    /**
94	     * Get the data that this form submits. The returned list is a copy of the data, and changes to the contents of the
95	     * list will not be reflected in the DOM.
96	     * @return a list of key vals
97	     */
98	    public List<Connection.KeyVal> formData() {
99	        ArrayList<Connection.KeyVal> data = new ArrayList<>();
100	
101	        // iterate the form control elements and accumulate their values
102	        Elements formEls = elements();
103	        for (Element el: formEls) {
104	            if (!el.tag().isFormSubmittable()) continue; // contents are form listable, superset of submitable
105	            if (el.hasAttr("disabled")) continue; // skip disabled form inputs
106	            String name = el.attr("name");
107	            if (name.length() == 0) continue;
108	            String type = el.attr("type");
109	
110	            if (type.equalsIgnoreCase("button") || type.equalsIgnoreCase("image")) continue; // browsers don't submit these
111	
112	            if (el.nameIs("select")) {
113	                Elements options = el.select("option[selected]");
114	                boolean set = false;
115	                for (Element option: options) {
