import org.jsoup.Jsoup;
import org.jsoup.nodes.*;
import org.jsoup.Connection;
public class Fp {
    static String data(FormElement f) {
        StringBuilder sb = new StringBuilder();
        for (Connection.KeyVal kv : f.formData()) {
            if (sb.length()>0) sb.append('&');
            sb.append(kv.key()).append('=').append(kv.value());
        }
        return sb.toString();
    }
    public static void main(String[] a) {
        System.out.println("hidden disabled: [" + data(Jsoup.parse(
            "<form id=f><input type=hidden name=h value=H disabled><input name=t value=T></form>").expectForm("#f")) + "]");
        System.out.println("reset/submit: [" + data(Jsoup.parse(
            "<form id=f><input type=reset name=r value=R><input type=submit name=s value=S></form>").expectForm("#f")) + "]");
        System.out.println("hidden in disabled fs: [" + data(Jsoup.parse(
            "<form id=f><fieldset disabled><input type=hidden name=h value=H></fieldset></form>").expectForm("#f")) + "]");
        System.out.println("disabled select: [" + data(Jsoup.parse(
            "<form id=f><select name=s disabled><option value=a selected></select></form>").expectForm("#f")) + "]");
        System.out.println("nested select: [" + data(Jsoup.parse(
            "<form id=f><select name=o><option value=inner selected></select><select name=s><option value=outer selected></select></form>").expectForm("#f")) + "]");
        // dynamically nested select
        Document doc = Jsoup.parse("<form id=f><select name=s><option value=a selected><option value=b></select></form>");
        FormElement f = doc.expectForm("#f");
        System.out.println("dyn before: [" + data(f) + "]");
        Element inner = new Element("select").attr("name","i");
        inner.appendElement("option").attr("value","x").attr("selected","selected");
        doc.selectFirst("select").appendChild(inner);
        System.out.println("dyn after: [" + data(f) + "]");
    }
}
