            if (legend == null || !isDescendant(control, legend)) return true;
            // control is inside the exempt first legend; continue checking ancestors outside of this fieldset
            ancestor = ancestor.parent();
        } else {
            ancestor = ancestor.parent();
        }
    }
    return false;
}

